d = json.load(sys.stdin)
# Find all keys containing 'port' or 'server' or 'host'
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(x in k.lower() for x in ['port','server','host','bind','listen']):
                print(f'{path}.{k} = {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
